/**
 * Static data for the GitHub Pages demo.
 *
 * Every file imported here is generated by `scripts/generate_demo_data.py`, which
 * runs the same deterministic electrical engine as the API. There are no API
 * keys, tokens, user records, or network calls in this bundle.
 */

import agentCatalogJson from "@/lib/demo/agent-catalog.json";
import agentRunsJson from "@/lib/demo/agent-runs.json";
import buildJson from "@/lib/demo/build.json";
import electricalJson from "@/lib/demo/electrical.json";
import orchestrationJson from "@/lib/demo/orchestration.json";
import projectJson from "@/lib/demo/project.json";
import { assetPath, DEMO_PROJECT_ID } from "@/lib/constants";
import type {
  AgentCatalog,
  AgentRun,
  BuildArtifact,
  ElectricalArtifact,
  ExportFormat,
  OrchestrationResult,
  Project,
  ProjectSummary,
} from "@/lib/types";

export const demoProject = projectJson as unknown as Project;
export const demoAgentRuns = agentRunsJson as unknown as AgentRun[];
export const demoAgentCatalog = agentCatalogJson as unknown as AgentCatalog;
export const demoElectrical = electricalJson as unknown as ElectricalArtifact;
export const demoBuild = buildJson as unknown as BuildArtifact;
export const demoOrchestration = orchestrationJson as unknown as OrchestrationResult;

export const demoProjectSummaries: ProjectSummary[] = [
  {
    id: demoProject.id,
    name: demoProject.name,
    slug: demoProject.slug,
    description: demoProject.description,
    robot_type: demoProject.robot_type,
    status: demoProject.status,
    difficulty: demoProject.difficulty,
    budget_max_usd: demoProject.budget_max_usd,
    created_at: demoProject.created_at,
    updated_at: demoProject.updated_at,
  },
];

export function demoProjectById(projectId: string): Project | null {
  return projectId === DEMO_PROJECT_ID ? demoProject : null;
}

export function demoExportPath(format: ExportFormat): string {
  const descriptor = demoElectrical.export_formats.find((item) => item.format === format);
  const filename = descriptor?.filename ?? "electrical-plan.json";
  return assetPath(`/demo/exports/${filename}`);
}

export function isDemoProject(projectId: string): boolean {
  return projectId === DEMO_PROJECT_ID;
}
